        public void Print(
            IPackageGetter item,
            StructuredStringBuilder sb,
            string? name = null,
            Package.Mask<bool>? printMask = null)
        {
            if (name == null)
            {
                sb.AppendLine($"Package =>");
            }
            else
            {
                sb.AppendLine($"{name} (Package) =>");
            }
            using (sb.Brace())
            {
                ToStringFields(
                    item: item,
                    sb: sb,
                    printMask: printMask);
            }
        }
        
